// Blog posts batch 3 (2026-10-16): slow cooking, rubs and steak technique. Rules in posts-blog.js.
import { BLOG_KEYWORDS } from './posts-blog-keywords.js'

const meta = (slug) => ({ slug, kw: BLOG_KEYWORDS[slug].focus, keywords: BLOG_KEYWORDS[slug].keywords, date: '2026-10-16', updated: '2026-10-16' })

export const BLOG_POSTS_3 = [
  {
    ...meta('pulled-beef-recipe'),
    title: 'Pulled Beef Recipe: Slow Cooker, Oven and Mexican-Style',
    seoTitle: 'Easy Pulled Beef Recipe: Slow Cooker or Oven',
    excerpt: `A pulled beef recipe that shreds with a fork: the right cut, a smoky rub, slow cooker and oven timings, a Mexican pulled beef variation and serving ideas.`,
    body: [
      ['p', `Pulled beef is one of the most generous things you can cook. A single, inexpensive piece of beef, rubbed with spices and cooked slowly for hours, collapses into tender, juicy shreds that can fill burger buns, tacos, wraps and baked potatoes for a crowd. It needs almost no skill, just the right cut and enough time. This pulled beef recipe gives you a slow cooker method, an oven method and a Mexican-style variation, plus tips for getting the texture just right.`],
      ['h2', `Choosing the right cut`],
      ['p', `Pulled beef relies on connective tissue. Over many hours at a low temperature, the collagen that makes some cuts tough breaks down into gelatin, which lubricates the muscle fibres so they pull apart easily and stay moist. Lean cuts do not have enough of it, so they dry out and turn stringy. The best choices are:`],
      ['ul', [
        `Chuck: the most popular choice. Our [chuck steak](/product/beef-chuck-meat-steak/) and [chuck tender](/product/beef-chuck-tender/) both shred beautifully.`,
        `Brisket: rich and beefy. A [point end brisket](/product/beef-point-end-brisket/) is fattier and more forgiving than the leaner flat.`,
        `[Beef cheeks](/product/buy-beef-cheeks/): incredibly tender and gelatinous, perfect for tacos.`,
        `[Bolar blade](/product/beef-bolar-blade-roast/): an economical shoulder roast that pulls well.`,
      ]],
      ['h3', `Why not the best cut of beef for steak?`],
      ['p', `It is tempting to think a more expensive cut will give better pulled beef, but the opposite is true. The best cut of beef for steak, such as eye fillet or porterhouse, is tender because it has very little connective tissue. In a slow cooker that same lack of collagen leaves it dry and grainy. Save premium steaks for the grill and use the cheaper, harder-working cuts for pulling.`],
      ['h2', `Smoky pulled beef rub`],
      ['p', `This rub is enough for 1.5 to 2 kg of beef.`],
      ['ul', [
        `2 tablespoons brown sugar`,
        `1 tablespoon smoked paprika`,
        `2 teaspoons each of salt, garlic powder and onion powder`,
        `1 teaspoon each of ground cumin, black pepper and dried oregano`,
        `1/2 teaspoon chilli powder or cayenne (optional)`,
      ]],
      ['p', `Mix the rub, pat the beef dry and coat it all over. If you have time, leave it covered in the fridge for a few hours or overnight so the salt seasons the meat more deeply.`],
      ['h2', `Pulled beef slow cooker method`],
      ['p', `The slow cooker is the easiest way to make pulled beef. Heat a tablespoon of oil in a heavy pan and sear the rubbed beef on all sides until well browned; this step is optional but adds a lot of flavour. Slice two onions into the base of the slow cooker and place the beef on top. Mix 1 cup of beef stock with 2 tablespoons of tomato paste, 2 tablespoons of apple cider vinegar or malt vinegar, and 1 tablespoon of Worcestershire-style sauce (check the label is alcohol-free) or soy sauce, and pour it around the beef.`],
      ['p', `Cook on low for 8 to 10 hours, or on high for 5 to 6 hours, until the beef falls apart when pressed with a fork. Lift the beef onto a board, shred it with two forks, and discard any large pieces of fat. Skim the fat from the cooking liquid, then pour enough of the liquid back over the meat to keep it moist and glossy.`],
      ['h2', `Oven method`],
      ['p', `Heat the oven to 150°C. Sear the beef in a heavy, ovenproof pot, add the onions and liquid, cover tightly and cook for 4 to 5 hours, turning the beef once or twice. The oven gives slightly more concentrated flavour because some liquid evaporates. Shred and moisten with the juices as above. For a bark-like crust, finish the shredded beef on a tray under a hot grill for a few minutes until the edges crisp.`],
      ['h2', `Mexican pulled beef`],
      ['p', `For Mexican pulled beef in the style of barbacoa or shredded beef tacos, swap the rub for 2 teaspoons ground cumin, 2 teaspoons dried oregano, 1 teaspoon smoked paprika, 1 teaspoon ground coriander, 1/2 teaspoon cinnamon and salt. Blend 2 to 3 chipotle chillies in adobo with 4 cloves of garlic, the juice of 2 limes, 1 tablespoon of vinegar and 1/2 cup of beef stock, and pour it over the beef with a couple of bay leaves. Cook as above. Shred and toss with the juices and a handful of chopped coriander.`],
      ['p', `Serve in warm corn tortillas with diced onion, coriander, lime wedges and a fresh salsa, or pile it into burrito bowls with rice, beans and avocado. For crispy taco meat, fry the shredded beef in a hot pan with a little of its fat until the edges are golden.`],
      ['h2', `How to serve pulled beef`],
      ['ul', [
        `In soft buns with coleslaw and pickles.`,
        `In tacos, burritos and quesadillas.`,
        `Over loaded fries or baked potatoes with cheese and sour cream.`,
        `In toasted sandwiches with melted cheese.`,
        `Stirred through pasta with a rich tomato sauce.`,
        `As a topping for nachos at a party.`,
      ]],
      ['h3', `A better roast beef roll`],
      ['p', `If you were about to search for roast beef roll near me, consider making your own with pulled beef. Pile warm, juicy shredded beef into a crusty roll with a spoon of the cooking juices, some caramelised onion, mustard and rocket. It is just as satisfying and feeds the whole family for the price of a couple of shop-bought rolls.`],
      ['h2', `Storing and freezing`],
      ['p', `Pulled beef keeps for four days in the fridge in a sealed container with some of its cooking liquid. It freezes very well for up to three months: portion it into bags with a little liquid, flatten them so they freeze and thaw quickly, and label them. Reheat gently in a covered pan with a splash of stock until piping hot.`],
      ['h2', `Pulled beef recipe questions`],
      ['h3', `Why is my pulled beef tough?`],
      ['p', `It needs more time. If the meat resists when you try to shred it, the collagen has not fully broken down. Put it back in and check again every 45 minutes. Pulled beef is ready when it collapses with almost no pressure.`],
      ['h3', `Should the beef be covered with liquid?`],
      ['p', `No. A cup or so of liquid is enough, because the beef releases its own juices as it cooks. Too much liquid boils the meat and dilutes the flavour.`],
      ['h3', `How much raw beef do I need per person?`],
      ['p', `Beef loses about a third of its weight during slow cooking. Allow roughly 200 g of raw beef per person for generous servings, or 150 g if you are serving plenty of sides.`],
      ['h3', `Can I smoke pulled beef?`],
      ['p', `Yes. Smoke a chuck roll or brisket at 110 to 120°C until it reaches about 95°C internally, wrapping it in foil or butcher paper once the bark has set. Our guide to the [best temperature to smoke beef brisket](/blog/best-temperature-to-smoke-beef-brisket/) explains the process.`],
      ['h2', `Buy beef for pulled beef`],
      ['p', `Chuck, brisket, cheeks and bolar blade are all in our [halal beef range](/shop/halal-beef/). Every cut is certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia. Orders over $500 are delivered free; for big events, see our [bulk meat boxes](/shop/bulk-meat-boxes/).`],
    ],
  },
  {
    ...meta('braised-beef'),
    title: 'Braised Beef: Cheeks, Noodle Soup and a Classic Braise',
    seoTitle: 'Braised Beef Recipe: Tender Cheeks and Soup',
    excerpt: `Braised beef made simple: a classic braised beef recipe, red-braised beef cheeks, a Taiwanese-style braised beef noodle soup and the best halal cuts.`,
    body: [
      ['p', `Braising is the most forgiving cooking method in the kitchen. Brown the meat, add some liquid and aromatics, cover the pot and let low heat do the rest. A few hours later, cheap, tough cuts have become tender and the liquid has turned into a rich, glossy sauce. Braised beef appears in almost every cuisine, from French pot-au-feu to Chinese red-braised beef to Italian stracotto. This guide gives you a master braised beef recipe, then shows you how to turn the same technique into braised beef cheeks and a deeply flavoured noodle soup.`],
      ['h2', `How braising works`],
      ['p', `Hard-working muscles, such as the cheek, shin and shoulder, are full of collagen. Cooked quickly, collagen is tough and chewy. Held at a gentle simmer, between about 80 and 95°C, for two to four hours, it slowly dissolves into gelatin. That gelatin gives braised beef its melting texture and makes the sauce silky. The key is gentle heat: a fierce boil tightens the muscle fibres and squeezes out moisture, so even a long-cooked braise can end up dry if it bubbles too hard.`],
      ['h2', `Best cuts for braising`],
      ['ul', [
        `[Beef cheeks](/product/buy-beef-cheeks/): the most luxurious braise, almost spoonable when done.`,
        `[Gravy beef](/product/gravy-beef/) and [beef shin](/product/beef-shin-hammer/): rich and gelatinous, perfect for soups.`,
        `[Chuck steak](/product/beef-chuck-meat-steak/): reliable, well marbled and affordable.`,
        `[Beef short ribs](/product/buy-beef-short-ribs/): meaty, rich and impressive on the plate.`,
        `[Osso buco](/product/beef-osso-buco/): shin on the bone, with marrow that enriches the sauce.`,
        `[Beef oxtail](/product/beef-oxtail/): very gelatinous and deeply flavoured.`,
      ]],
      ['h2', `Master braised beef recipe`],
      ['p', `Serves six. This European-style braise is the foundation for many variations.`],
      ['ul', [
        `1.5 kg chuck, cheeks or short ribs, cut into large pieces`,
        `Salt, pepper and 2 tablespoons plain flour`,
        `3 tablespoons oil`,
        `1 onion, 2 carrots and 2 celery sticks, diced`,
        `4 cloves garlic, sliced`,
        `2 tablespoons tomato paste`,
        `750 ml beef stock`,
        `2 tablespoons balsamic or red vinegar, for depth`,
        `2 bay leaves and a few sprigs of thyme and rosemary`,
      ]],
      ['p', `Season the beef and dust it lightly with flour. Brown it well in batches in a heavy casserole, then set it aside. Lower the heat, add the vegetables and cook for 10 minutes until soft and golden. Stir in the garlic and tomato paste for 2 minutes. Add the vinegar, scrape up the browned bits, then the stock and herbs. Return the beef, bring to a bare simmer, cover and cook in a 150°C oven for 3 to 3.5 hours, until tender. Lift out the beef, reduce the sauce on the stove until it coats a spoon, and season to taste.`],
      ['h2', `Braised beef cheeks, Chinese-style`],
      ['p', `Red-braised braised beef cheeks are a showstopper with very little effort. Brown 4 trimmed beef cheeks in a little oil. Remove them, then fry a thumb of sliced ginger, 4 garlic cloves and 4 spring onions for a minute. Add 2 star anise, 1 cinnamon stick, a strip of dried mandarin peel if you have it, 1/4 cup light soy, 2 tablespoons dark soy, 2 tablespoons brown sugar or rock sugar and 3 cups of water or stock. Return the cheeks, cover and simmer very gently for 3 hours, turning occasionally. Uncover for the last 30 minutes so the sauce becomes sticky and glossy. Serve over rice with steamed greens. Our full guide to [slow cooked beef cheeks](/blog/slow-cooked-beef-cheeks/) has more methods.`],
      ['h2', `Braised beef noodle soup`],
      ['p', `Taiwan's famous braised beef noodle soup is built on the same idea: tender braised shin or brisket in a rich, spiced broth, served with chewy wheat noodles and greens. This halal home version leaves out the rice wine used in many recipes.`],
      ['ul', [
        `1 kg beef shin or gravy beef, in large chunks`,
        `1 tablespoon chilli bean paste (check the label) and 1 tablespoon tomato paste`,
        `1 onion, 4 garlic cloves, a thumb of ginger and 4 spring onions`,
        `2 star anise, 1 cinnamon stick, 2 bay leaves and 1 teaspoon Sichuan peppercorns`,
        `1/4 cup light soy, 1 tablespoon dark soy and 1 tablespoon sugar`,
        `2 litres beef stock or water`,
        `Fresh wheat noodles, bok choy and pickled mustard greens to serve`,
      ]],
      ['p', `Blanch the beef in boiling water for 3 minutes, drain and rinse; this keeps the broth clear. Fry the aromatics in oil, add the chilli bean paste and tomato paste, then the spices, soy and sugar. Add the beef and stock, simmer gently, partly covered, for 2 to 2.5 hours until tender. Cook the noodles and greens separately, place them in bowls, ladle over the broth and beef, and top with spring onion, coriander and pickled greens.`],
      ['h2', `Leftover braised beef ideas`],
      ['p', `Braises improve overnight, and leftovers are versatile. Shred them into pies, pasta sauces, toasted sandwiches or fried rice. Many cooks also turn leftover braised beef into croquettes: mix the shredded meat with mashed potato and a little sauce, shape, crumb and fry. If you have been looking for beef croquettes where to buy them ready-made, try making them at home from leftovers instead. Our [beef croquettes](/blog/beef-croquettes/) guide explains how.`],
      ['h3', `Using mince in a quick braise`],
      ['p', `Short on time? A quick "braise" of mince in a rich sauce, such as a bolognese or keema, gives some of the same comfort in under an hour. Some retailers label their leanest mince as 5 star beef mince; in our range, the leanest option is [extra lean beef mince](/product/extra-lean-beef-mince/), while [premium beef mince](/product/premium-beef-mince/) has a little more fat for flavour.`],
      ['h2', `Braised beef questions`],
      ['h3', `Do I have to brown the beef?`],
      ['p', `Browning is not essential for tenderness, but it adds a deeper flavour and colour to the sauce. For Chinese-style braises, blanching instead of browning gives a cleaner broth.`],
      ['h3', `How much liquid should a braise have?`],
      ['p', `The liquid should come about two-thirds of the way up the meat, not cover it completely. This gives a more concentrated sauce.`],
      ['h3', `Can I braise in a slow cooker?`],
      ['p', `Yes. Brown the beef and cook the aromatics on the stove, then transfer everything to the slow cooker with about a third less liquid. Cook on low for 8 hours, then reduce the sauce on the stove.`],
      ['h3', `Why is my braise greasy?`],
      ['p', `Slow-cooking cuts release fat as they cook. Chill the finished braise overnight and lift off the set fat, or skim it with a ladle while hot.`],
      ['h2', `Buy halal beef for braising`],
      ['p', `Cheeks, shin, chuck, short ribs, osso buco and oxtail are all available from our [halal beef range](/shop/halal-beef/) and [offal range](/shop/offal-beef-organ-meat/). Every product is certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('beef-shank'),
    title: 'Beef Shank: What It Is and the Best Ways to Cook It',
    seoTitle: 'Beef Shank Guide: Tender, Slow-Cooked Recipes',
    excerpt: `Beef shank explained: the cut, osso buco and boneless shin, how long to braise it, three reliable recipes and how to buy halal beef shanks online.`,
    body: [
      ['p', `Beef shank is the lower leg of the animal, and it is one of the most flavourful and economical cuts you can buy. Because the leg works constantly, the muscle is lean but laced with connective tissue, and often comes with a section of marrow-filled bone. Cooked quickly, it is tough. Cooked slowly, it becomes meltingly tender and turns its cooking liquid into a rich, gelatinous sauce. This guide explains the different ways beef shanks are sold, how to cook them, and three recipes to start with.`],
      ['h2', `What is beef shank?`],
      ['p', `The shank comes from the leg, above the hoof and below the knee or elbow. The front leg is called the foreshank and the back leg the hindshank. In Australia, you will usually see shank meat sold in a few forms:`],
      ['ul', [
        `[Osso buco](/product/beef-osso-buco/): cross-cut slices of shank, 3 to 4 cm thick, with a round of marrow bone in the centre.`,
        `[Gravy beef](/product/gravy-beef/): boneless shin meat, cut into pieces for stews and soups.`,
        `[Beef shin hammer](/product/beef-shin-hammer/): a whole shank on the bone, slow-roasted as a dramatic centrepiece.`,
        `[Veal osso buco](/product/veal-osso-buco/): from younger animals, smaller and more delicate.`,
      ]],
      ['p', `All of these are beef shank meat, and all need long, slow cooking.`],
      ['h2', `Why beef shanks are worth cooking`],
      ['p', `Beef shanks have three things going for them. First, flavour: the muscle is deeply beefy, much more so than tender steak cuts. Second, texture: the collagen breaks down into a silky, sticky gelatin that makes the meat juicy and the sauce glossy. Third, the bone: marrow adds richness to the sauce, and many people consider it the best bite on the plate. And because shank is a less sought-after cut, it is excellent value.`],
      ['h2', `How long to cook beef shank`],
      ['p', `As a rule, beef shank needs:`],
      ['ul', [
        `2.5 to 3.5 hours in a 150 to 160°C oven, covered`,
        `2.5 to 3 hours at a gentle simmer on the stove`,
        `8 to 10 hours on low in a slow cooker`,
        `45 to 60 minutes at high pressure in a pressure cooker`,
      ]],
      ['p', `It is ready when the meat pulls away from the bone easily and a fork slides in with no resistance. A whole shin hammer takes longer, about 5 to 6 hours at 140°C.`],
      ['h2', `Recipe 1: classic osso buco`],
      ['p', `Season 4 pieces of osso buco and dust them with flour. Brown them well in olive oil in a wide, heavy casserole and set them aside. Soften a diced onion, carrot and celery stick in the pan, then add 3 garlic cloves and 2 tablespoons of tomato paste. Add a 400 g can of crushed tomatoes, 500 ml beef stock, a strip of lemon peel and a few thyme sprigs. Return the meat in a single layer, cover and cook in a 160°C oven for 2.5 to 3 hours. Finish with gremolata: finely chopped parsley, lemon zest and garlic. Serve with soft polenta, mashed potato or risotto.`],
      ['h2', `Recipe 2: spiced beef shank curry`],
      ['p', `In South Asian kitchens, beef shank is the cut of choice for nihari, a slow-cooked, deeply spiced stew. Brown 1.2 kg of osso buco or shin on the bone, then add 2 tablespoons of nihari masala (or a mix of garam masala, ground ginger, fennel and chilli), a tablespoon of ginger-garlic paste and enough water to cover. Simmer very gently for 4 to 5 hours, then thicken the sauce with a few tablespoons of flour mixed into water. Serve topped with fried onions, julienned ginger, coriander, green chilli and lemon, with naan.`],
      ['h2', `Recipe 3: beef shank soup`],
      ['p', `Simmer 1 kg of beef shank with an onion, a thumb of ginger, 2 star anise, a cinnamon stick and 2 litres of water for 2.5 hours, skimming occasionally. Remove the meat, slice it, and season the broth with soy sauce or salt. Serve the broth over rice noodles with the sliced shank, bean sprouts, herbs and lime. It is a simple, clean-tasting version of the beef noodle soups found across Asia.`],
      ['h2', `Tips for cooking shank`],
      ['ul', [
        `Tie osso buco around the circumference with kitchen string so it keeps its shape.`,
        `Brown well for flavour, but keep the braise at a gentle simmer.`,
        `Cook it a day ahead: chilled overnight, the fat sets on top and can be lifted off.`,
        `Serve the marrow with a small spoon or on toast.`,
      ]],
      ['h2', `Beef shank vs mince for quick meals`],
      ['p', `Shank is a weekend cut, not a weeknight one. For fast family dinners, a 500g beef mince pack becomes a bolognese, cottage pie or tacos in under 40 minutes. If you buy mince beef online alongside your shanks, you can cook the slow braise on Sunday and have quick mince meals ready for the week. Our [premium beef mince](/product/premium-beef-mince/) and [extra lean beef mince](/product/extra-lean-beef-mince/) both freeze well.`],
      ['h2', `Beef shank questions`],
      ['h3', `Is beef shank the same as osso buco?`],
      ['p', `Osso buco is beef shank cut crossways with the bone in. All osso buco is shank, but shank is also sold boneless (gravy beef) or whole (shin hammer).`],
      ['h3', `Can I grill beef shank?`],
      ['p', `Not successfully. It needs long, moist cooking to break down its connective tissue. Grilled quickly, it is very chewy.`],
      ['h3', `How much shank per person?`],
      ['p', `Allow one osso buco piece (about 300 to 400 g with bone) per person, or 200 g of boneless gravy beef.`],
      ['h3', `Can I freeze cooked shank?`],
      ['p', `Yes, for up to three months, in its sauce. Thaw overnight in the fridge and reheat gently until piping hot.`],
      ['h2', `Making stock from shank bones`],
      ['p', `After serving osso buco, keep the bones. Roast them with any leftover bones from the week, an onion and a carrot at 200°C until browned, then simmer them in water for four to six hours with a bay leaf and peppercorns. Strain, chill and lift off the fat, and you have a rich beef stock for soups, risotto and your next braise. For a bigger batch, add some [beef bones for soup](/product/beef-bones-for-soup/). Our guide to the [best bones for bone broth](/blog/best-bones-for-bone-broth/) explains which bones give the most gelatin.`],
      ['h2', `Buy halal beef shanks online`],
      ['p', `Osso buco, gravy beef, shin hammer and veal osso buco are all in our [halal beef range](/shop/halal-beef/), along with [beef marrow bones](/product/beef-marrow-bones/) for stock. Every cut is certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('slow-cooker-beef-ribs'),
    title: 'Slow Cooker Beef Ribs: Sticky, Tender and Easy',
    seoTitle: 'Slow Cooker Beef Ribs: Tender and Easy',
    excerpt: `How to make slow cooker beef ribs that fall off the bone: choosing short ribs or spare ribs, a sticky glaze, timings and finishing them under the grill.`,
    body: [
      ['p', `Slow cooker beef ribs are one of the easiest ways to get barbecue-style results without a smoker. Brown the ribs, add a simple braising liquid, leave them for eight hours, then finish them under a hot grill with a sticky glaze. The meat becomes so tender it slips off the bone, and the slow cooker does nearly all of the work. This guide explains which beef ribs to buy, how long to cook them, and how to make a glaze that caramelises beautifully.`],
      ['h2', `Which beef ribs to buy`],
      ['p', `Not all beef ribs are the same. The two main types are:`],
      ['ul', [
        `[Beef short ribs](/product/buy-beef-short-ribs/): cut from the lower rib cage and chuck area, with a thick layer of meat on top of each bone. The meatiest option and the best for slow cooking.`,
        `[Asado cut ribs](/product/beef-asado-cut-ribs/): short ribs cut thinly across the bones, so each strip has several small bone sections. They cook a little faster and are popular for grilling and braising.`,
      ]],
      ['p', `Beef spare ribs, sometimes called back ribs or dinosaur ribs, come from the upper rib cage behind the prime rib. They have less meat between the bones and more on top. Any of these can be slow-cooked, but short ribs give the most generous result.`],
      ['h3', `Beef and rib cuts explained`],
      ['p', `Customers often ask about the different beef and rib cuts on the menu. The rib section of the animal gives several famous cuts: the boneless scotch fillet, the bone-in rib-eye and tomahawk, and the standing rib roast. The ribs below them, where the meat thins out and becomes fattier and more sinewy, give short ribs and asado. The premium cuts are for fast cooking; the ribs underneath are for slow cooking.`],
      ['h2', `Slow cooker beef ribs recipe`],
      ['p', `Serves four.`],
      ['ul', [
        `1.5 to 2 kg beef short ribs`,
        `Salt, pepper and 1 tablespoon smoked paprika`,
        `1 tablespoon oil`,
        `1 onion, sliced, and 4 cloves garlic`,
        `1 cup beef stock`,
        `1/2 cup barbecue sauce (check the label for alcohol-based ingredients)`,
        `2 tablespoons soy sauce`,
        `2 tablespoons brown sugar and 2 tablespoons apple cider vinegar`,
      ]],
      ['h3', `Method`],
      ['p', `Season the ribs well with salt, pepper and paprika. Heat the oil in a heavy pan and brown the ribs on all sides, in batches, until deeply coloured; this adds a lot of flavour. Place the onion and garlic in the slow cooker and lay the ribs on top, bone side up if possible. Mix the stock, barbecue sauce, soy, sugar and vinegar and pour it over.`],
      ['p', `Cook on low for 8 to 9 hours or on high for 5 to 6 hours, until the meat is very tender and pulling away from the bone. Carefully lift the ribs onto a lined baking tray. Strain the cooking liquid into a saucepan, skim off the fat, and boil it for 10 to 15 minutes until it reduces to a sticky glaze.`],
      ['p', `Heat the grill (broiler) to high. Brush the ribs generously with the glaze and grill them for 3 to 5 minutes, watching closely, until the glaze bubbles and caramelises. Brush again and serve with the remaining glaze on the side.`],
      ['h2', `Beef spare ribs crockpot variations`],
      ['p', `If you are making beef spare ribs crockpot style, cut the rack into two- or three-bone sections so they fit, and reduce the cooking time by an hour, as they have less meat. Some favourite flavour variations:`],
      ['ul', [
        `Korean-style: soy, brown sugar, garlic, ginger, sesame oil and grated pear, finished with sesame seeds and spring onions.`,
        `Middle Eastern: pomegranate molasses, garlic, cumin, cinnamon and a little honey.`,
        `Smoky barbecue: chipotle, smoked paprika, tomato and molasses.`,
        `Asian sticky: hoisin, soy, five-spice and honey.`,
      ]],
      ['h2', `Tips for perfect slow cooker ribs`],
      ['ul', [
        `Brown the ribs first for colour and flavour.`,
        `Do not add too much liquid; ribs release their own juices.`,
        `Reduce the cooking liquid to make a proper glaze.`,
        `Finish under the grill or on a barbecue for a sticky, caramelised surface.`,
        `Cook a day ahead, chill, and lift off the set fat for a cleaner sauce.`,
      ]],
      ['h2', `Beef striploin vs sirloin and other steak questions`],
      ['p', `While you are buying ribs, you may want a steak for another night. A common question is beef striploin vs sirloin: in Australia they are the same muscle. Striploin is the whole boneless piece, and sirloin or porterhouse steaks are cut from it. Our guide to [sirloin vs porterhouse vs rump](/blog/sirloin-vs-porterhouse-vs-rump/) explains the naming in detail.`],
      ['h2', `Using leftovers`],
      ['p', `Leftover rib meat is fantastic shredded into tacos, toasted sandwiches, fried rice or pasta sauce. Strip it from the bone while warm, store it in its glaze, and use within three days. It also freezes for up to three months.`],
      ['h3', `Turn leftovers into a mince-style ragu`],
      ['p', `Chopped finely, leftover rib meat behaves a lot like mince in a sauce. Simmer it with tomatoes, onion and herbs for a rich ragu over pasta or polenta, or use it in place of mince in a cottage pie.`],
      ['h2', `Slow cooker beef ribs questions`],
      ['h3', `Do I need to remove the membrane?`],
      ['p', `Short ribs do not have the thick membrane that back ribs do. For back or spare ribs, peel off the silvery membrane on the bone side with a paper towel for better texture.`],
      ['h3', `Can I cook beef ribs from frozen?`],
      ['p', `It is safer and better to thaw them completely in the fridge first. Frozen ribs spend too long in the temperature danger zone in a slow cooker and do not brown.`],
      ['h3', `How many ribs per person?`],
      ['p', `Allow around 400 to 500 g of bone-in short ribs per person, as much of the weight is bone and fat.`],
      ['h2', `Side dishes for beef ribs`],
      ['p', `Sticky ribs need sides that are fresh and crunchy. A tangy coleslaw, grilled corn with butter and lime, a crisp green salad or a simple potato salad all balance the richness. Soft bread rolls or cornbread are perfect for mopping up the glaze, and pickles add a sharp contrast. For a bigger barbecue spread, serve them with [beef skewers](/blog/beef-skewers/) and a big bowl of rice.`],
      ['p', `Ribs reheat well too: warm them covered in a 160°C oven with a splash of stock for 20 minutes, then brush with glaze and flash them under the grill.`],
      ['h2', `Buy halal beef ribs`],
      ['p', `Short ribs and asado ribs are in our [halal beef range](/shop/halal-beef/), along with every other cut you need. Every product is certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, Australia-wide.`],
    ],
  },
  {
    ...meta('beef-brisket-rub'),
    title: 'Beef Brisket Rub: Three Recipes and How to Apply Them',
    seoTitle: 'Best Beef Brisket Rub Recipes and Tips',
    excerpt: `A beef brisket rub for every style: a Texas salt-and-pepper rub, a sweet and smoky seasoning rub, a bold spice rub, plus how much to use and when to apply it.`,
    body: [
      ['p', `A great brisket starts long before the smoker is lit. The rub seasons the meat, helps build the dark, crusty bark that barbecue lovers prize, and sets the flavour of the whole cook. Some pitmasters swear by nothing more than salt and pepper; others build complex blends with sugar, paprika and chilli. This guide gives you three reliable beef brisket rub recipes, explains what each ingredient does and shows you how to apply it for the best bark.`],
      ['h2', `What a rub does`],
      ['p', `A dry rub has three jobs. Salt seasons the meat and, given time, moves into the muscle to improve flavour and moisture retention. Pepper and spices add flavour to the crust. And sugar, if used, caramelises and darkens the bark. During a long cook, the rub mixes with rendered fat and smoke to form the dark, flavourful bark on the outside of the brisket.`],
      ['h2', `Rub 1: Texas-style salt and pepper`],
      ['p', `The classic Central Texas brisket uses a "Dalmatian rub": equal parts coarse kosher salt and coarse black pepper, by volume. Some pitmasters add a little garlic powder. Its simplicity lets the beef and smoke shine.`],
      ['ul', [
        `1/2 cup coarse black pepper (16-mesh if you can find it)`,
        `1/2 cup coarse kosher salt or flaky salt`,
        `1 tablespoon garlic powder (optional)`,
      ]],
      ['h2', `Rub 2: beef brisket seasoning rub, sweet and smoky`],
      ['p', `This beef brisket seasoning rub has a little sugar for a deeper, more caramelised bark and a gently sweet finish that suits sliced brisket rolls and sandwiches.`],
      ['ul', [
        `1/4 cup coarse salt`,
        `1/4 cup coarse black pepper`,
        `2 tablespoons brown sugar`,
        `2 tablespoons smoked paprika`,
        `1 tablespoon each garlic powder and onion powder`,
        `1 teaspoon each ground cumin and mustard powder`,
      ]],
      ['p', `Because sugar burns at high temperatures, use this rub only for low-and-slow cooking at 120°C or below.`],
      ['h2', `Rub 3: bold beef brisket spice rub`],
      ['p', `For a beef brisket spice rub with more complexity, add warm spices and chilli. It works particularly well for brisket that will be served in tacos, wraps or with a spicy sauce.`],
      ['ul', [
        `1/4 cup coarse salt and 1/4 cup coarse black pepper`,
        `2 tablespoons ancho or mild chilli powder`,
        `1 tablespoon each smoked paprika, ground coriander and ground cumin`,
        `1 tablespoon each garlic powder and onion powder`,
        `1 teaspoon each cayenne pepper and dried oregano`,
        `1/2 teaspoon ground cinnamon`,
      ]],
      ['h2', `How much rub to use`],
      ['p', `A good rule is about 1 tablespoon of rub per 500 g of brisket, or roughly 1/2 cup for a 5 kg whole brisket. You want an even coating that you can still see the meat through, not a thick paste. Too much rub can make the bark overly salty and bitter.`],
      ['h2', `When and how to apply it`],
      ['p', `Trim the brisket first, removing hard fat and leaving about 5 mm of fat on the fat cap. Pat it dry. Some cooks apply a thin "binder" of mustard, oil or hot sauce to help the rub stick; it is optional, and the flavour of the binder largely disappears during cooking. Sprinkle the rub evenly from about 30 cm above so it falls in an even layer, and press it gently into the meat. Season all sides, including the edges.`],
      ['p', `You can apply the rub just before cooking, or up to 24 hours ahead. Rubbing the night before and leaving the brisket uncovered in the fridge lets the salt penetrate and dries the surface slightly, which helps the bark form. For a sugar-based rub, apply it just before cooking to avoid drawing out too much moisture.`],
      ['h2', `Choosing your brisket`],
      ['p', `A whole brisket has two parts: the lean flat and the fatty point. For your first cook, a [point end brisket](/product/beef-point-end-brisket/) is the most forgiving because its fat keeps it moist. A [whole brisket](/product/buy-beef-brisket-whole/) or [packer cut](/product/packer-cut-beef-brisket-navel-end/) gives you both muscles and the full barbecue experience.`],
      ['h3', `Is brisket the cheapest cut of beef?`],
      ['p', `Brisket has a reputation as a cheap cut, and decades ago it really was among the cheapest cut of beef options in many butcher shops. Its popularity in barbecue has pushed demand up, but it is still excellent value compared with premium steaks, especially for feeding a crowd.`],
      ['h3', `Wagyu brisket`],
      ['p', `If you have been searching wagyu near me for a special cook, Wagyu brisket is a rich, heavily marbled upgrade that stays incredibly juicy. Our [Wagyu brisket](/product/wagyu-beef-brisket-mb9/) is delivered chilled across Australia.`],
      ['h2', `Rub tips from the pit`],
      ['ul', [
        `Use coarse salt and pepper; fine powders cake and burn.`,
        `Mix rubs in a shaker so you can apply them evenly.`,
        `Make a big batch and store it in an airtight jar for up to six months.`,
        `Taste the rub before using it: it should be well seasoned but not overwhelmingly salty.`,
        `Do not rub the brisket and then wrap it in plastic for days; it can cure the surface.`,
      ]],
      ['h2', `Beef brisket rub questions`],
      ['h3', `Do I need a binder?`],
      ['p', `No. The natural moisture on the brisket's surface is usually enough. A binder can help the rub stick more evenly, but it does not noticeably change the flavour.`],
      ['h3', `Can I use these rubs on other cuts?`],
      ['p', `Yes. They work brilliantly on beef ribs, chuck roasts, tri-tip and lamb shoulder.`],
      ['h3', `What temperature should I smoke brisket at?`],
      ['p', `Most pitmasters cook brisket between 107 and 135°C. Our guide to the [best temperature to smoke beef brisket](/blog/best-temperature-to-smoke-beef-brisket/) explains the options in detail.`],
      ['h2', `Storing and gifting your rub`],
      ['p', `Homemade rubs keep for up to six months in an airtight glass jar away from heat and light. Ground spices slowly lose their aroma, so make batches you will use within that time and label each jar with the date. Rubs also make a thoughtful gift for barbecue-loving friends: fill small jars, add a label with the recipe and cooking tips, and pair them with a brisket from our range for a special occasion. Remember that sugar-based rubs can clump in humid weather; a few grains of uncooked rice in the jar help keep them free-flowing.`],
      ['p', `Whatever rub you choose, write down what you used and how the brisket turned out, so you can adjust the next one.`],
      ['h2', `Buy halal brisket online`],
      ['p', `Whole brisket, packer cut, point end and Wagyu brisket are all in our [halal beef range](/shop/halal-beef/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, Australia-wide. For catering, see our [brisket cryovac carton](/product/beef-brisket-cryovac-carton/).`],
    ],
  },
  {
    ...meta('how-to-tenderise-beef-steak'),
    title: 'How to Tenderise Beef Steak: 7 Methods That Work',
    seoTitle: 'How to Tenderise Beef Steak: 7 Easy Methods',
    excerpt: `How to tenderise beef steak at home: pounding, salting, marinades, baking soda for stir-fry, slicing and cooking methods, plus which cuts need it.`,
    body: [
      ['p', `Tender steak is the goal of every home cook, but not every cut starts out tender, and even good steaks can turn chewy with the wrong treatment. The good news is that there are several simple, reliable ways to make beef more tender, from pounding and salting to marinating, slicing and choosing the right cooking method. This guide explains how to tenderise beef steak with seven methods, when to use each one, and which cuts benefit most.`],
      ['h2', `Why some steaks are tough`],
      ['p', `Tenderness depends on three things: the muscle the steak comes from, how much connective tissue it has, and how it is cooked. Muscles that do little work, such as the eye fillet, are naturally tender. Muscles that work hard, such as the shoulder, leg and flank, have more and tougher connective tissue and coarser fibres. Overcooking any steak tightens the fibres and squeezes out moisture, making even premium cuts tough. Tenderising helps by physically breaking up fibres, changing the meat's chemistry, or shortening the fibres you chew.`],
      ['h2', `1. Choose the best cut of steak for the job`],
      ['p', `The simplest way to get a tender steak is to start with one. The best cut of steak for tenderness is the [eye fillet](/product/beef-eye-fillet-steaks/), followed by [scotch fillet](/product/scotch-fillet-ribeye-steaks/) and [porterhouse](/product/sirloin-steak-beef-porterhouse/). [Rump](/product/rump-beef-steaks/) is firmer but full of flavour, and benefits from some of the methods below. For the barbecue, the best steak for bbq is usually scotch fillet: its marbling keeps it juicy over high heat and forgives a few extra seconds on the grill.`],
      ['h2', `2. Pound it`],
      ['p', `Pounding with a meat mallet breaks up muscle fibres and connective tissue and evens out the thickness. It is ideal for schnitzels, minute steaks and thin steaks for sandwiches. Place the steak between sheets of baking paper and pound from the centre outwards to an even thickness. A tenderiser with a spiked face is more aggressive and good for tougher cuts such as topside.`],
      ['h2', `3. Salt it ahead (dry brining)`],
      ['p', `Salting a steak at least 40 minutes, and up to 24 hours, before cooking makes it juicier and more tender. Salt first draws moisture out, then that salty liquid is reabsorbed and begins to break down some of the muscle proteins. Use about 1 teaspoon of kosher salt per 500 g of steak, and leave it uncovered on a rack in the fridge. The dry surface also gives a better sear.`],
      ['h2', `4. Use a marinade (with care)`],
      ['p', `Acidic marinades (lemon, vinegar, yoghurt) and enzyme-rich ingredients (pineapple, papaya, kiwi fruit, grated pear) can tenderise the surface of meat. Yoghurt and grated pear are gentle and effective; fresh pineapple and kiwi are powerful and can turn meat mushy if left for more than an hour or two. Marinades only penetrate a few millimetres, so they work best on thin cuts and small pieces.`],
      ['h2', `5. Tenderize beef with baking soda`],
      ['p', `To tenderize beef with baking soda, a technique Chinese cooks call velveting, toss thinly sliced beef with a small amount of bicarbonate of soda: about 1/2 teaspoon per 500 g, dissolved in a tablespoon of water. Leave it for 15 to 20 minutes, then rinse well and pat dry. The baking soda raises the pH on the meat's surface, which makes it harder for the proteins to bond tightly during cooking, so the beef stays soft and juicy. This is the best way to tenderise beef for stir fry.`],
      ['p', `After rinsing, many cooks add a light marinade of soy sauce, cornflour and oil, which coats the beef and protects it in the hot wok. Our [rainbow beef](/blog/rainbow-beef/) recipe uses this method.`],
      ['h2', `6. Slice against the grain`],
      ['p', `Even a tough steak becomes more tender if you shorten the fibres you have to chew. Look at the cooked steak and find the direction of the muscle fibres, then slice across them, not along them. This matters most with flank, skirt and hanger, but it improves every steak.`],
      ['h2', `7. Cook it correctly`],
      ['p', `The right cooking method is often the most effective tenderiser. Tender cuts should be cooked quickly to medium-rare or medium. Tougher cuts with lots of connective tissue, such as chuck, blade and shin, become tender only with long, slow, moist cooking. Trying to grill those cuts quickly is the most common cause of tough beef. Our guide to [medium rare beef steak temperature](/blog/medium-rare-beef-steak-temperature/) covers cooking times.`],
      ['h2', `How do I tenderise beef for different dishes?`],
      ['p', `If you are asking "how do I tenderise beef" for a particular meal, here is a quick guide:`],
      ['ul', [
        `Stir-fry: slice thinly across the grain and use baking soda or a cornflour marinade.`,
        `Schnitzel: pound thin, then crumb.`,
        `Steak on the grill: dry brine for a few hours and cook to medium-rare.`,
        `Kebabs: marinate in yoghurt or grated onion for 4 to 12 hours.`,
        `Stew or curry: choose a collagen-rich cut and simmer gently for 2 hours or more.`,
      ]],
      ['h2', `Buying steak: quality over discounts`],
      ['p', `It can be tempting to wait for steaks on sale, but the most reliable way to get a tender steak is to buy the right cut, store it well and cook it properly. If you have been searching for steaks halal near me, we deliver certified halal steaks across Australia from our depot in Greenacre, Sydney, so you can choose exactly the cut and thickness you want.`],
      ['h2', `Tenderising questions`],
      ['h3', `Does a meat tenderiser powder work?`],
      ['p', `Commercial powders use enzymes such as papain (from papaya). They work on the surface but can make meat mushy if overused. Read the label carefully, and use them sparingly.`],
      ['h3', `Can I tenderise a steak after cooking?`],
      ['p', `Not really, but slicing it thinly across the grain makes it much easier to eat. Tough leftover steak is also great chopped into fried rice or simmered in a sauce.`],
      ['h3', `Does resting make steak more tender?`],
      ['p', `Resting does not change the fibres, but it lets the juices redistribute so less moisture runs out when you slice, which makes the steak taste juicier and more tender.`],
      ['p', `If you are cooking a thin steak quickly for a sandwich, resting for just a minute or two is enough. Thick steaks and roasts need longer: around 5 to 10 minutes for steaks and 15 to 20 for roasts.`],
      ['h2', `Buy tender halal steak online`],
      ['p', `Eye fillet, scotch fillet, porterhouse, rump and Wagyu steaks are all in our [halal beef range](/shop/halal-beef/), certified halal by Halal Control Australia and delivered chilled Australia-wide.`],
    ],
  },
  {
    ...meta('medium-rare-beef-steak-temperature'),
    title: 'Medium Rare Beef Steak Temperature and Cooking Times',
    seoTitle: 'Medium Rare Beef Steak Temperature: Easy Guide',
    excerpt: `The medium rare beef steak temperature (55 to 57°C), when to pull the steak off, cooking times by thickness and cut, and how to cook it perfectly every time.`,
    body: [
      ['p', `Medium-rare is the doneness most chefs recommend for a good steak: warm, rosy pink from edge to edge, juicy and tender. Getting there reliably is easy once you understand two numbers, the target temperature and the pull temperature, and a few simple techniques. This guide covers the correct medium rare beef steak temperature, how to cook medium rare steak in a pan or on the barbecue, cooking times by thickness, and which cuts suit it best.`],
      ['h2', `The target temperature`],
      ['p', `A medium-rare steak has a core temperature of about 55 to 57°C after resting. At this temperature, the fat has started to soften and render, the muscle fibres are firm but not tight, and the meat is pink and juicy throughout. For reference:`],
      ['table', { caption: 'Steak doneness temperatures (after resting)', head: ['Doneness', 'Core temperature', 'Pull off the heat at'], rows: [['Rare', '50 to 52°C', '46 to 48°C'], ['Medium-rare', '55 to 57°C', '51 to 53°C'], ['Medium', '60 to 63°C', '56 to 58°C'], ['Medium-well', '65 to 68°C', '61 to 63°C'], ['Well done', '70°C and above', '66°C']] }],
      ['h2', `Why pull the steak early`],
      ['p', `A steak keeps cooking after you take it off the heat, because heat continues to move from the hot outside to the cooler centre. This "carryover cooking" usually adds 3 to 5°C to a typical steak, and more to a thick one. So for medium-rare, take the steak off the heat at about 51 to 53°C and let it rest for 5 to 10 minutes. An instant-read thermometer inserted horizontally into the thickest part is by far the most reliable way to check.`],
      ['h2', `How to cook medium rare steak in a pan`],
      ['ul', [
        `Take the steak out of the fridge 30 to 45 minutes ahead and pat it dry.`,
        `Season generously with salt just before cooking (or 40 minutes or more ahead).`,
        `Heat a heavy frying pan, ideally cast iron, until it is very hot.`,
        `Add a thin film of high-smoke-point oil and lay the steak in.`,
        `Cook without moving it for 2 to 3 minutes until a deep crust forms, then turn.`,
        `Turn every minute or so after that for even cooking, and check the temperature.`,
        `In the final minute, add butter, garlic and herbs and baste if you like.`,
        `Remove at 51 to 53°C and rest for 5 to 10 minutes.`,
      ]],
      ['h2', `How long to cook medium rare steak`],
      ['p', `If you are wondering how long to cook medium rare steak, the answer depends on thickness, starting temperature and the heat of your pan. As a guide, for a very hot pan or grill and a steak at room temperature:`],
      ['table', { caption: 'Steak cooking times medium rare (total, turning regularly)', head: ['Steak thickness', 'Approximate total time', 'Rest'], rows: [['1.5 cm', '3 to 4 minutes', '3 minutes'], ['2.5 cm', '5 to 7 minutes', '5 minutes'], ['3.5 cm', '8 to 10 minutes', '8 minutes'], ['5 cm and thicker', 'Reverse sear: see below', '10 minutes']] }],
      ['p', `These steak cooking times medium rare are a starting point. Always confirm with a thermometer or the touch test, because grills and pans vary enormously.`],
      ['h3', `Reverse searing thick steaks`],
      ['p', `For steaks 4 cm or thicker, such as a [tomahawk](/product/beef-tomahawk-steaks/) or [T-bone](/product/beef-steak-t-bone/), cook them gently first and sear them last. Place the seasoned steak on a rack in a 110 to 120°C oven until it reaches 45 to 48°C inside (30 to 50 minutes), then sear in a smoking-hot pan for 1 minute a side. You get an even pink centre and a great crust.`],
      ['h2', `The touch test`],
      ['p', `Without a thermometer, press the centre of the steak with your finger. Rare feels very soft, like the fleshy part of your palm below the thumb when your hand is relaxed. Medium-rare has a gentle spring, like that same spot when you touch your thumb to your index finger. It takes practice, so use a thermometer while you learn.`],
      ['h2', `The best steak cut for medium-rare`],
      ['p', `Medium-rare suits almost every steak, but some shine particularly well. The best steak cut for medium-rare depends on what you like:`],
      ['ul', [
        `[Scotch fillet](/product/scotch-fillet-ribeye-steaks/): rich and juicy; its marbling renders beautifully at medium-rare.`,
        `[Porterhouse](/product/sirloin-steak-beef-porterhouse/): firm and beefy, at its best at medium-rare.`,
        `[Eye fillet](/product/beef-eye-fillet-steaks/): very tender and lean; never cook past medium.`,
        `[Rump](/product/rump-beef-steaks/): full of flavour; medium-rare keeps it tender.`,
        `[Wagyu](/wagyu-steak/): heavily marbled; many prefer medium-rare to medium so the fat fully softens.`,
      ]],
      ['h2', `Why buy from a steak butcher`],
      ['p', `A good steak butcher can cut steaks to an even thickness, which is the secret to even cooking. Thin, uneven steaks overcook at the edges before the centre is ready. Aim for steaks at least 2.5 cm thick for a juicy medium-rare. If you have been searching for steak halal near me, we cut and deliver certified halal steaks Australia-wide, and you can compare each steak price per kilo on the product pages before you order.`],
      ['h2', `Medium-rare steak questions`],
      ['h3', `Is medium-rare steak safe?`],
      ['p', `Whole-muscle steaks are generally considered safe to eat medium-rare, because any bacteria are mostly on the surface and are killed by searing. Minced beef and burgers are different and should be cooked to 75°C. Pregnant women, young children and people with weakened immune systems may prefer steaks cooked to medium or beyond.`],
      ['h3', `Why is my medium-rare steak grey around the edges?`],
      ['p', `The heat was too low or the steak was cooked for too long on each side. Use a hotter pan, turn more often, or use the reverse sear method for thick steaks.`],
      ['h3', `Does resting really matter?`],
      ['p', `Yes. It lets carryover cooking finish and allows juices to settle, so far less ends up on the plate when you cut it.`],
      ['h2', `Choosing a meat thermometer`],
      ['p', `A good instant-read digital thermometer is the single most useful tool for cooking steak. Look for one that reads in two to three seconds and has a thin probe, so you do not lose juices through a large hole. Insert it horizontally from the side of the steak into the very centre, avoiding bone and fat, which give misleading readings. For thick steaks and roasts, a leave-in probe thermometer with an alarm lets you cook without opening the oven or barbecue lid.`],
      ['p', `Check the accuracy of your thermometer occasionally by placing the probe in a glass of iced water: it should read 0°C. If it is off by a degree or two, remember the difference or calibrate it according to the manufacturer's instructions.`],
      ['h2', `Medium-rare on the barbecue`],
      ['p', `Barbecues vary much more than pans, so a two-zone fire is the most reliable approach. Set one side to high and leave the other side on low or off. Sear the steak over the hot side for 1 to 2 minutes a side to build a crust, then move it to the cooler side and close the lid until it reaches 51 to 53°C. This prevents flare-ups from charring the outside before the centre is ready.`],
      ['h2', `Buy halal steak online`],
      ['p', `Every steak in our [halal beef range](/shop/halal-beef/) is certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('beef-steak-side-dishes'),
    title: 'Beef Steak Side Dishes: 15 Ideas for Every Season',
    seoTitle: 'Best Beef Steak Side Dishes: 15 Easy Ideas',
    excerpt: `Beef steak side dishes for every night and every season: potatoes, salads, vegetables, sauces and grains that turn a simple steak into a complete meal.`,
    body: [
      ['p', `A great steak deserves great company. The right side dish balances the richness of the beef, adds colour and texture to the plate, and turns a simple steak into a satisfying meal. Whether you want a classic steakhouse spread, a quick weeknight salad or something a little different, this list of beef steak side dishes has an option for every night, season and budget.`],
      ['h2', `How to choose a side dish for beef steak`],
      ['p', `A good side dish for beef steak usually does one of three things. It can contrast with the steak: crisp, fresh, acidic salads cut through richness. It can complement it: creamy potatoes and buttery mushrooms echo the steak's savoury depth. Or it can add something new: grains, pulses and roasted vegetables bring different textures and flavours. Aim for one starchy side and one fresh or vegetable side for a balanced plate.`],
      ['h2', `Potato sides`],
      ['h3', `1. Crispy roast potatoes`],
      ['p', `Par-boil peeled, chunked potatoes for 8 minutes, drain, shake to rough up the edges and roast in hot oil at 220°C for 45 minutes, turning once. For extra crunch, try our [duck fat potatoes](/blog/duck-fat-potatoes/).`],
      ['h3', `2. Creamy mashed potato`],
      ['p', `Boil floury potatoes until tender, mash with warm milk and plenty of butter, and season well. Stir through roasted garlic or chopped chives for a twist.`],
      ['h3', `3. Hand-cut chips`],
      ['p', `Cut potatoes into thick chips, soak in cold water for 30 minutes, dry well and cook in an air fryer or oven at 200°C until golden, or double-fry them for the classic steak frites.`],
      ['h3', `4. Potato gratin`],
      ['p', `Thinly sliced potatoes baked in cream, garlic and a little cheese until golden and bubbling. It can be made ahead and reheated, which makes it ideal for entertaining.`],
      ['h2', `Salads`],
      ['h3', `5. Rocket and parmesan salad`],
      ['p', `Peppery rocket, shaved parmesan, a squeeze of lemon and good olive oil. It takes two minutes and is one of the best partners for a rich steak.`],
      ['h3', `6. Classic garden salad`],
      ['p', `Crisp lettuce, cucumber, tomato and red onion with a simple vinaigrette. Fresh, crunchy and good with any cut.`],
      ['h3', `7. Tomato and red onion salad`],
      ['p', `Ripe tomatoes sliced and dressed with olive oil, salt, finely sliced red onion and fresh basil or oregano. Best in summer, when tomatoes are at their peak.`],
      ['h3', `8. Coleslaw`],
      ['p', `Shredded cabbage and carrot with a creamy or vinegar-based dressing adds crunch and tang, especially for barbecued steaks.`],
      ['h2', `Vegetables`],
      ['h3', `9. Garlic butter mushrooms`],
      ['p', `Pan-fry thickly sliced mushrooms in butter until golden, then add garlic, thyme and a splash of stock. They double as a sauce for the steak.`],
      ['h3', `10. Grilled corn`],
      ['p', `Corn on the cob grilled until charred, brushed with butter and sprinkled with salt, chilli and lime.`],
      ['h3', `11. Roasted vegetables`],
      ['p', `Pumpkin, carrots, capsicum, zucchini and red onion tossed in oil and roasted until caramelised. A great way to use whatever is in the fridge.`],
      ['h3', `12. Green beans with almonds`],
      ['p', `Blanched green beans tossed with butter, lemon zest and toasted flaked almonds. Light, bright and quick.`],
      ['h2', `Grains and something different`],
      ['h3', `13. Tabbouleh`],
      ['p', `Parsley, mint, tomato, onion and bulgur with lemon and olive oil. A fresh, herby partner for grilled steak and lamb.`],
      ['h3', `14. Herbed rice or couscous`],
      ['p', `Fluffy rice or couscous stirred through with herbs, lemon and toasted nuts. It soaks up the steak juices beautifully.`],
      ['h3', `15. Creamed spinach`],
      ['p', `A steakhouse classic: wilted spinach in a garlicky cream sauce with a pinch of nutmeg.`],
      ['h2', `Sauces that make steak dishes special`],
      ['p', `Good steak dishes often hinge on the sauce. Try a creamy pepper sauce, a mushroom sauce, chimichurri, salsa verde, garlic butter or a simple béarnaise-style butter sauce flavoured with tarragon and lemon. Each beef steak side dish above pairs well with at least one of these, so you can mix and match through the week.`],
      ['h2', `Choosing the steak`],
      ['p', `The best steak cuts for a classic steak dinner are [scotch fillet](/product/scotch-fillet-ribeye-steaks/), [porterhouse](/product/sirloin-steak-beef-porterhouse/), [eye fillet](/product/beef-eye-fillet-steaks/) and [rump](/product/rump-beef-steaks/). For a special occasion, a [T-bone](/product/beef-steak-t-bone/) or [tomahawk](/product/beef-tomahawk-steaks/) makes an impressive centrepiece. Our [scotch fillet vs porterhouse vs eye fillet](/blog/scotch-fillet-vs-porterhouse-vs-eye-fillet/) guide compares the most popular cuts.`],
      ['h3', `Butcher steak cuts worth trying`],
      ['p', `If you want something different, try a butcher steak such as [hanger](/product/beef-hanger-steak/), [flank](/product/flank-steak-beef/) or [flat iron](/product/flat-iron-steak-beef-oyster-blade/). These cuts are full of flavour, usually better value, and pair brilliantly with fresh salads and punchy sauces.`],
      ['h2', `Steak side dish questions`],
      ['h3', `What is the most popular side with steak?`],
      ['p', `Potatoes in some form, whether chips, mash or roasted, are the most popular. A simple green salad comes a close second.`],
      ['h3', `What is a healthy side for steak?`],
      ['p', `Roasted or steamed vegetables, a big leafy salad, grilled corn or tabbouleh are all light, fresh options.`],
      ['h3', `How many sides should I serve?`],
      ['p', `Two is usually enough: one starch and one vegetable or salad. For entertaining, three or four sides make a generous spread.`],
      ['h2', `Planning a steak night menu`],
      ['p', `For a relaxed steak night at home, plan the sides around your timing. Start with anything that takes longest, such as roast potatoes or a gratin, which can sit in a low oven while you cook the steak. Prepare salads and dressings ahead but dress them at the last minute so they stay crisp. Make sauces in advance and reheat them gently, or cook a quick pan sauce in the steak pan while the meat rests.`],
      ['p', `A balanced menu for four might be: scotch fillet steaks, crispy roast potatoes, garlic butter mushrooms and a rocket and parmesan salad, with a pepper sauce on the side. For a summer barbecue, try porterhouse with grilled corn, tomato salad and tabbouleh. For a winter dinner, eye fillet with creamy mash, green beans with almonds and a mushroom sauce. Each menu needs only one burner for the steak, so it is easy to cook in a home kitchen.`],
      ['p', `If you are feeding children, simple sides such as chips, corn and a basic salad tend to be the most popular, and you can slice the steak thinly to make it easier for them to eat.`],
      ['p', `Leftover sides are useful too: roast vegetables become a frittata, and potatoes make crispy hash for breakfast.`],
      ['h2', `Buy steak online`],
      ['p', `You can buy steak for every occasion from our [halal beef range](/shop/halal-beef/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, Australia-wide. Steak prices vary by cut and grade, so compare the price per kilo on each product page. Orders over $500 ship free.`],
    ],
  },
  {
    ...meta('pasta-with-beef-steak'),
    title: 'Pasta With Beef Steak: Five Easy Recipes',
    seoTitle: 'Pasta With Beef Steak: 5 Easy Recipes',
    excerpt: `Five recipes for pasta with beef steak, from creamy garlic steak fettuccine to a quick tomato and chilli penne, plus which steak to buy and how to cook it.`,
    body: [
      ['p', `Steak and pasta might seem like an unusual pairing, but together they make a quick, hearty and impressive meal. Sliced, perfectly seared steak tossed through pasta in a creamy, garlicky or tomato-based sauce is restaurant-worthy food you can make at home in about 30 minutes. It is also a smart way to stretch one or two steaks to feed a family. This guide shares five easy beef steak and pasta recipes, explains which cuts work best and how to cook the steak so it stays tender.`],
      ['h2', `Which steak to use`],
      ['p', `For pasta, you want a steak that has good flavour and stays tender when sliced. The best cuts of steak for this are:`],
      ['ul', [
        `[Rump](/product/rump-beef-steaks/): flavourful and good value; our top pick for everyday pasta.`,
        `[Porterhouse](/product/sirloin-steak-beef-porterhouse/): tender with a neat shape that slices well.`,
        `[Scotch fillet](/product/scotch-fillet-ribeye-steaks/): juicy and rich, for a special dinner.`,
        `[Eye fillet](/product/beef-eye-fillet-steaks/): the most tender, ideal with a creamy sauce.`,
      ]],
      ['p', `The best cut of meat steak for pasta is one you can cook to medium-rare and slice thinly. Avoid slow-cooking cuts such as chuck, which become chewy when cooked quickly. Allow about 150 g of steak per person.`],
      ['h2', `How to cook the steak for pasta`],
      ['p', `Pat the steak dry and season with salt and pepper. Sear it in a very hot pan with a little oil, 3 to 4 minutes a side for a 2.5 cm steak, to medium-rare. Rest it for 5 minutes, then slice thinly across the grain. Use the same pan to start the sauce, so the browned bits from the steak add flavour. Add the sliced steak to the pasta at the very end so it warms through without overcooking.`],
      ['h2', `1. Creamy garlic steak fettuccine`],
      ['p', `Cook 400 g fettuccine. In the steak pan, melt 2 tablespoons butter and fry 4 crushed garlic cloves for 1 minute. Add 300 ml cream and 1/2 cup grated parmesan and simmer for 3 minutes. Toss the pasta in the sauce with a splash of pasta water, add the sliced steak and a handful of baby spinach, and finish with black pepper and parsley.`],
      ['h2', `2. Tomato and chilli steak penne`],
      ['p', `Fry a sliced onion and 3 garlic cloves in olive oil until soft. Add a 400 g can of crushed tomatoes, a pinch of chilli flakes and a teaspoon of sugar and simmer for 15 minutes. Toss with 400 g cooked penne, the sliced steak, torn basil and some grated parmesan.`],
      ['h2', `3. Mushroom and pepper steak pasta`],
      ['p', `Fry 250 g sliced mushrooms in butter until golden. Add 2 teaspoons crushed black peppercorns, 1 cup beef stock and 1/2 cup cream, and simmer until slightly thickened. Toss with cooked rigatoni and sliced steak. It tastes like a classic pepper steak in pasta form.`],
      ['h2', `4. Pesto steak spaghetti`],
      ['p', `Toss hot spaghetti with basil pesto, a little pasta water, halved cherry tomatoes and the sliced steak. Top with toasted pine nuts and parmesan. A fresh, fast dinner that is ready in 20 minutes.`],
      ['h2', `5. Asian-style steak noodles`],
      ['p', `For a different take on beef steak pasta recipes, toss cooked spaghetti or egg noodles with a sauce of soy, a little honey, garlic, ginger, sesame oil and chilli. Add the sliced steak, stir-fried capsicum and spring onions. Finish with sesame seeds and coriander.`],
      ['h2', `Tips for the best beef steak and pasta`],
      ['ul', [
        `Salt the pasta water well; it should taste lightly salty.`,
        `Reserve a cup of pasta water before draining; its starch helps the sauce cling.`,
        `Cook the steak to medium-rare, as it will warm further in the sauce.`,
        `Slice thinly across the grain for tenderness.`,
        `Add the steak last and serve immediately.`,
      ]],
      ['h2', `Using leftover steak`],
      ['p', `Pasta with beef steak is a brilliant way to use leftover grilled steak. Slice cold steak thinly and add it to the sauce just long enough to warm through. Avoid reheating it on its own, which tends to overcook it.`],
      ['h2', `Buying steak for pasta`],
      ['p', `When you make a steak purchase for pasta, you do not need the most expensive cut. The price of a steak varies widely between cuts and grades, and rump or porterhouse give excellent results at a sensible price. Compare prices per kilo on our product pages, and choose steaks about 2.5 cm thick for easy, even cooking. Our guide to [beef steak side dishes](/blog/beef-steak-side-dishes/) has ideas for what to serve alongside.`],
      ['h2', `Pasta with beef steak questions`],
      ['h3', `Which pasta shape is best?`],
      ['p', `Long, flat pasta such as fettuccine or tagliatelle suits creamy sauces. Tubes such as penne and rigatoni hold chunky tomato and mushroom sauces well.`],
      ['h3', `Can I use mince instead?`],
      ['p', `Yes, for a different style of dish. Mince makes a classic bolognese or a baked pasta; see our [beef pasta bake](/blog/beef-pasta-bake/) recipe.`],
      ['h3', `How do I stop the steak getting tough?`],
      ['p', `Cook it quickly over high heat, rest it, slice thinly across the grain, and add it to the pasta at the end. Never simmer sliced steak in the sauce.`],
      ['h3', `Can I make it ahead?`],
      ['p', `The sauce can be made ahead and reheated, but cook the pasta and steak fresh for the best texture.`],
      ['h2', `Planning ahead for busy weeknights`],
      ['p', `Steak pasta is a great candidate for planned leftovers. When you cook steaks for dinner, add one extra and refrigerate it whole once it has cooled. The next night, slice it thinly and toss it through a quick pasta in the final minute of cooking. Cooked steak keeps for up to three days in the fridge in a sealed container.`],
      ['p', `You can also prepare the sauces ahead. Tomato and chilli sauce keeps for four days in the fridge and freezes well for three months. Pesto keeps for a week with a layer of olive oil on top. Creamy sauces are best made fresh, as they can split when reheated, but they take only five minutes. With a sauce ready and a steak in the fridge, dinner is on the table in the time it takes to boil the pasta.`],
      ['p', `For families with mixed tastes, cook a plain pasta and let everyone add their own sauce, steak, cheese and vegetables at the table.`],
      ['p', `A simple green salad with a sharp vinaigrette is all you need on the side.`],
      ['h2', `Buy halal steak online`],
      ['p', `Rump, porterhouse, scotch fillet and eye fillet are all in our [halal beef range](/shop/halal-beef/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('how-to-prepare-a-porterhouse'),
    title: 'How to Prepare a Porterhouse Steak for the Pan or Grill',
    seoTitle: 'How to Prepare a Porterhouse: Expert Tips',
    excerpt: `How to prepare a porterhouse steak: trimming and seasoning, how long to cook porterhouse for each doneness, pan and barbecue methods, and resting tips.`,
    body: [
      ['p', `Porterhouse is one of Australia's favourite steaks. It is firm, beefy and juicy, with a strip of fat along one edge that bastes the meat as it cooks. It is also one of the easiest steaks to cook well, as long as you prepare it properly and do not overcook it. This guide explains how to prepare a porterhouse from fridge to plate: choosing the steak, trimming, seasoning, cooking times for every doneness, and resting and slicing.`],
      ['h2', `What is a porterhouse?`],
      ['p', `In Australia, porterhouse is a boneless steak cut from the striploin, the muscle that runs along the back between the ribs and the rump. It is called sirloin or New York strip in other countries. Confusingly, in the United States "porterhouse" means a large bone-in steak with both the strip and the tenderloin, which we call a T-bone. Our [sirloin porterhouse steaks](/product/sirloin-steak-beef-porterhouse/) are the boneless Australian cut.`],
      ['h2', `The best steak meat part for flavour and value`],
      ['p', `The striploin is often considered the best steak meat part for balance. It is more tender than rump, has more flavour than eye fillet, and costs less than scotch fillet. Its firm texture and clean, beefy taste make it ideal for grilling, pan-frying and slicing over salads. For a richer version, try our [Angus porterhouse](/product/angus-beef-porterhouse-steaks-mb3-4/) or [Wagyu porterhouse](/product/wagyu-beef-porterhouse-steaks-mb5/).`],
      ['h2', `How to prepare porterhouse steak before cooking`],
      ['ul', [
        `Choose a steak at least 2.5 cm thick. Thin steaks overcook before they brown.`,
        `Take it out of the fridge 30 to 45 minutes ahead so it cooks evenly.`,
        `Trim the fat cap to about 5 mm thick, and score it lightly every 2 cm so it does not curl.`,
        `Remove any silverskin from the edge with a sharp knife.`,
        `Pat the steak completely dry with paper towel.`,
        `Season generously with salt and pepper just before cooking, or salt it 40 minutes or more ahead.`,
      ]],
      ['h3', `To marinate or not?`],
      ['p', `Porterhouse has great flavour on its own and does not need a marinade. If you like, rub it with olive oil, garlic and rosemary an hour before cooking, but wipe off any bits of garlic, which burn in a hot pan.`],
      ['h2', `How long to cook porterhouse steak`],
      ['p', `For a 2.5 cm steak in a very hot pan or on a hot grill, turning every minute after the first sear:`],
      ['table', { caption: 'How long to cook porterhouse steak (2.5 cm thick)', head: ['Doneness', 'Total cooking time', 'Pull at', 'Rest'], rows: [['Rare', '4 to 5 minutes', '47°C', '5 minutes'], ['Medium-rare', '6 to 7 minutes', '52°C', '5 minutes'], ['Medium', '8 to 9 minutes', '57°C', '5 minutes'], ['Medium-well', '10 to 11 minutes', '62°C', '5 minutes']] }],
      ['p', `Porterhouse is at its best rare to medium. Beyond medium, the lean meat can become dry. An instant-read thermometer is the most reliable guide.`],
      ['h2', `Cooking porterhouse in a pan`],
      ['p', `Heat a heavy frying pan, preferably cast iron, until it is smoking hot. Add a thin film of oil. Hold the steak with tongs and press the fat edge onto the pan for 1 to 2 minutes to render and crisp it. Then lay the steak flat and sear for 2 minutes without moving it. Turn, and continue turning every minute until it reaches your pull temperature. In the last minute, add a knob of butter, a crushed garlic clove and a sprig of thyme, and spoon the foaming butter over the steak.`],
      ['h2', `The best steak for barbecue: porterhouse on the grill`],
      ['p', `Porterhouse is also one of the best steak for barbecue choices. Heat the barbecue to high and oil the grill bars. Cook the steak for 2 minutes, rotate it 90 degrees for crosshatch marks, cook for another 1 to 2 minutes, then turn and repeat. Move it to a cooler part of the grill if the outside browns too quickly. Use a thermometer to check doneness, as barbecues vary.`],
      ['h2', `Resting and slicing`],
      ['p', `Rest the steak on a warm plate or board for 5 minutes, loosely covered with foil. Serve it whole, or slice it across the grain into 1 cm strips and fan them on a plate, pouring any juices over the top. A sprinkle of flaky salt just before serving makes a big difference.`],
      ['h2', `What to serve with porterhouse`],
      ['p', `Classic pairings include chips, a green salad, garlic mushrooms, a creamy pepper sauce or chimichurri. Our guide to [beef steak side dishes](/blog/beef-steak-side-dishes/) has fifteen ideas.`],
      ['h2', `Buying porterhouse`],
      ['p', `Instead of waiting for a steak sale, buy porterhouse from a supplier who cuts to an even thickness. For a premium option, steak Angus lovers rate highly is our [Black Angus porterhouse](/product/angus-beef-porterhouse-steaks-mb3-4/), which has finer marbling. For entertaining, a [porterhouse portion](/product/porterhouse-beef-portion/) lets you cut steaks to any thickness or roast it whole.`],
      ['h2', `Porterhouse questions`],
      ['h3', `Is porterhouse the same as sirloin?`],
      ['p', `In Australia, yes: both names refer to steaks cut from the striploin. Our [sirloin vs porterhouse vs rump](/blog/sirloin-vs-porterhouse-vs-rump/) guide explains the naming in detail.`],
      ['h3', `Is porterhouse better than scotch fillet?`],
      ['p', `It depends on your taste. Porterhouse is firmer and leaner with a cleaner beef flavour; scotch fillet is more marbled, juicier and more forgiving. See our [scotch fillet vs porterhouse](/blog/scotch-fillet-vs-porterhouse-vs-eye-fillet/) comparison.`],
      ['h3', `Should I cook porterhouse from room temperature?`],
      ['p', `Taking the chill off for 30 to 45 minutes helps it cook more evenly, but it does not need to reach full room temperature. Never leave raw meat out for more than two hours.`],
      ['h2', `Quick pan sauces for porterhouse`],
      ['p', `While the steak rests, use the same pan to make a sauce in two or three minutes. For a pepper sauce, pour off most of the fat, add a tablespoon of butter and two teaspoons of crushed black peppercorns, then 150 ml of beef stock and 100 ml of cream; simmer until it coats a spoon. For a mushroom sauce, fry sliced mushrooms in the pan, add garlic, stock and a little cream. For a simple garlic and herb butter, mash softened butter with garlic, parsley and lemon zest and let a slice melt over the hot steak.`],
      ['p', `If you prefer something fresh, a spoon of chimichurri or salsa verde cuts through the richness of the fat cap. Make it ahead, as both improve after an hour in the fridge.`],
      ['h2', `Cooking porterhouse for a crowd`],
      ['p', `For more than four people, cooking individual steaks becomes a juggling act. Instead, roast a whole [porterhouse portion](/product/porterhouse-beef-portion/): sear it all over in a hot pan, then roast at 200°C until it reaches 52°C inside for medium-rare, about 30 to 40 minutes for a 2 kg piece. Rest for 15 minutes and slice thickly at the table. Everyone gets perfectly cooked beef at the same time.`],
      ['h2', `Buy halal porterhouse online`],
      ['p', `Porterhouse, Angus porterhouse and Wagyu porterhouse are all in our [halal beef range](/shop/halal-beef/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, Australia-wide.`],
    ],
  },
]
